//! App-owned XYZ raster tiles. The renderer never downloads map data.
use crate::*;
/// Explicit keyless provider metadata. This does not authorize network access or downloads.
pub fn provider(id:&str,name:&str,template:&str,attribution:&str,copyright_url:&str,osm:bool,offline_allowed:bool)->Value{json!({"id":id,"name":name,"template":template,"attribution":attribution,"copyright_url":copyright_url,"data":if osm{"osm"}else{"other"},"offline_allowed":offline_allowed})}
pub fn tile(x:u32,y:u32,file:&str)->Value{json!({"x":x,"y":y,"file":file})}
pub fn marker(latitude:f64,longitude:f64,label:&str)->Value{json!({"latitude":latitude,"longitude":longitude,"label":label})}
/// Put one viewer in a non-scrolling body. Tiles must be immutable private PNG/JPEG blobs.
pub fn viewer(id:&str,provider:Value,latitude:f64,longitude:f64,zoom:u8,tiles:Vec<Value>,markers:Vec<Value>)->Node{let mut n=node("map_viewer",id,"");n["provider"]=provider;n["latitude"]=json!(latitude);n["longitude"]=json!(longitude);n["zoom"]=json!(zoom);n["tiles"]=json!(tiles);n["markers"]=json!(markers);n}
/// XYZ center in tile units; longitude wraps, latitude clamps at the Mercator limit.
pub fn project(latitude:f64,longitude:f64,zoom:u8)->Result<(f64,f64),String>{if !latitude.is_finite()||!longitude.is_finite()||zoom>19{return Err("Invalid map coordinates".into())}let lat=latitude.clamp(-85.05112878,85.05112878).to_radians();let world=(1u32<<zoom)as f64;Ok((((longitude+180.).rem_euclid(360.))/360.*world,(1.-(lat.tan()+1./lat.cos()).ln()/std::f64::consts::PI)/2.*world))}
#[cfg(test)]mod tests{use super::*;#[test]fn maps_project_equator_dateline_and_poles(){assert_eq!(project(0.,0.,1).unwrap(),(1.,1.));assert_eq!(project(0.,180.,1).unwrap(),project(0.,-180.,1).unwrap());let(_,y)=project(90.,0.,2).unwrap();assert!(y.abs()<1e-9);assert!(project(f64::NAN,0.,1).is_err());assert!(project(0.,0.,20).is_err());}#[test]fn maps_helper_carries_explicit_provider_credits_and_private_handles(){let p=provider("demo","Demo","https://example.org/{z}/{x}/{y}.png","Demo data","https://example.org/license",false,false);let n=viewer("map",p,0.,0.,0,vec![tile(0,0,&"a".repeat(32))],vec![marker(0.,0.,"Center")]);assert_eq!(n["kind"],"map_viewer");assert_eq!(n["tiles"][0]["file"],"a".repeat(32));assert_eq!(n["provider"]["offline_allowed"],false);}}
/// Cache lookup is local. Offline mode requires provider permission and never returns a network request.
pub fn cached(map:&Node,x:u32,y:u32,offline:bool,then:&str)->Value{effect("maps.cache.lookup",json!({"map":map,"x":x,"y":y,"offline":offline}),then)}
/// Store a bounded binary HTTP response; caller must preserve the real response headers.
pub fn cache_response(map:&Node,x:u32,y:u32,response:Value,then:&str)->Value{effect("maps.cache.store",json!({"map":map,"x":x,"y":y,"response":response}),then)}
pub fn clear_cache(then:&str)->Value{effect("maps.cache.clear",json!({}),then)}
/// Use only after a local miss and an explicit user action. Signed network.http origin policy still applies.
pub fn fetch_cached_request(lookup:&Value,then:&str)->Result<Value,String>{if lookup["hit"]==true{return Err("Use the cached tile instead of fetching".into())}let request=lookup.get("request").filter(|v|v.is_object()).ok_or("Offline tile unavailable")?;Ok(effect("http.request",request.clone(),then))}
#[cfg(test)]mod cache_tests{use super::*;#[test]fn maps_cache_request_never_fetches_a_hit_or_offline_miss(){let hit=json!({"hit":true,"request":{"url":"https://example.org/tile"}});assert!(fetch_cached_request(&hit,"done").is_err());assert!(fetch_cached_request(&json!({"hit":false,"unavailable":true}),"done").is_err());let lookup=json!({"hit":false,"request":{"url":"https://example.org/tile","method":"GET","response":"hex","headers":{"If-None-Match":"\"tile\""}}});let e=fetch_cached_request(&lookup,"done").unwrap();assert_eq!(e["service"],"http.request");assert_eq!(e["args"]["headers"]["If-None-Match"],"\"tile\"");assert_eq!(cached(&json!({}),1,2,true,"done")["args"]["offline"],true);}}
pub fn viewport(map:&Node,width:u32,height:u32,offline:bool,then:&str)->Value{effect("maps.cache.viewport",json!({"map":map,"width":width,"height":height,"offline":offline}),then)}
/// Inverse Web Mercator in tile units; antimeridian wraps, poles clamp.
pub fn unproject(x:f64,y:f64,zoom:u8)->Result<(f64,f64),String>{if !x.is_finite()||!y.is_finite()||zoom>19{return Err("Invalid map coordinates".into())}let world=(1u32<<zoom)as f64;Ok((((std::f64::consts::PI*(1.-2.*y.clamp(0.,world)/world)).sinh()).atan().to_degrees().clamp(-85.05112878,85.05112878),x.rem_euclid(world)/world*360.-180.))}
